def read(n):return json.loads((B/n).read_text(encoding="utf-8"))
def validate(d):
    a=read("ibn-kathir-108-i09-symbolic-pairs-2026-11-02.json"); c=read("ibn-kathir-108-i09-clause-ownership-2026-11-01.json"); s=read("ibn-kathir-108-i09-exact-spans-2026-11-01.json"); q=read("ibn-kathir-108-i09-quraysh-scope-refinement-2026-11-02.json")
    assert {n:read(n) for n in PINS}==PINS,"Input drift"
    assert d["original_symbolic_document"]==a
    assert d["context_scopes"]==a["context_scopes"] and d["clause_locators"]==c["clauses"]
    assert d["holds"]==a["holds"]
    assert len(d["rows"])==7
    roles=["parallel_attributed_interpretation"]*2+["report_narration","embedded_reply","report_narration","authorial_grading","embedded_nested_allegation"]
    for i,(r,p) in enumerate(zip(d["rows"],a["pairs"])):
        expected=dict(p,source_unit=p.get("source_unit","108-I09-R02-REPORT"),reporting_author="Ibn Kathir",
          report_narrator="Ibn Abbas" if i in (2,3,4,6) else None,
          discourse_role=roles[i],source_locator_ref=p["evidence_ref"])
        assert r==expected,"Derivative speaker/source drift"
    for x in ("database_written","publication_ready","chapter_complete"):assert d[x] is False
    refs={x["id"]:x for x in s["locators"]}
    for x in refs.values():assert hashlib.sha256(x["text"].encode()).hexdigest()==x["sha256"]
    for x in c["clauses"]:
        p=refs[x["source_ref"]]; assert p["text"][x["start"]-p["start"]:x["end"]-p["start"]]==x["text"]
    for u in q["units"]:
        for lang in ("arabic","english"):
            x=u[lang]; p=refs[x["source_ref"]]
            assert p["text"][x["start"]-p["start"]:x["end"]-p["start"]]==x["text"]
def main():
    d=read("ibn-kathir-108-i09-normalized-offline-projection-2026-11-02.json");validate(d); mutations=[]
